    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer: "Cats often purr when they feel relaxed, but purring can also be a self-soothing behavior when they are stressed, recovering, or asking for attention."
        },
        {
          question: "How much sleep do cats need?",
          answer: "Most adult cats sleep around 12 to 16 hours a day. Kittens and senior cats may sleep even more because growing and aging both take extra energy."
        },
        {
          question: "Should cats drink milk?",
          answer: "Despite the classic image, many cats are lactose intolerant. Fresh water is the best daily drink, and treats made for cats are usually a safer choice than dairy."
        },
        {
          question: "Why does my cat knead blankets?",
          answer: "Kneading is a comforting behavior that begins in kittenhood. Adult cats may knead soft surfaces when they are settling in, marking a cozy spot, or showing trust."
        },
        {
          question: "How can I keep an indoor cat entertained?",
          answer: "Use a mix of climbing spaces, scratching posts, puzzle feeders, window perches, and short interactive play sessions. Rotating toys helps keep familiar objects interesting."
        }
      ];

      function FAQItem({ question, answer }, index) {
        const id = `faq-answer-${index + 1}`;

        return `
          <div class="example">
            <h2 class="question-heading">
              <button class="question-button" type="button" aria-expanded="true" aria-controls="${id}">
                <span>${question}</span>
                <span class="indicator" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="${id}">
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQPage({ items }) {
        return `
          <main class="page-shell" id="main-content">
            <section class="hero" aria-labelledby="page-title">
              <div>
                <p class="eyebrow">Cat care basics</p>
                <h1 id="page-title">Cat FAQ</h1>
                <p class="hero-copy">
                  Quick, practical answers to common questions about feline habits,
                  health, comfort, and everyday enrichment.
                </p>
              </div>
              <div class="cat-card">
                <div class="cat-icon" aria-hidden="true">🐾</div>
                <p>Small routines can make a big difference for curious cats.</p>
              </div>
            </section>

            <section class="faq-list" aria-label="Frequently asked questions about cats">
              ${items.map(FAQItem).join("")}
            </section>

            <footer>
              <p>For health concerns, contact a veterinarian who knows your cat.</p>
            </footer>
          </main>
        `;
      }

      function initDisclosures() {
        document.querySelectorAll(".question-button").forEach((button) => {
          const panel = document.getElementById(button.getAttribute("aria-controls"));

          button.setAttribute("aria-expanded", "false");
          panel.hidden = true;

          button.addEventListener("click", () => {
            const isOpen = button.getAttribute("aria-expanded") === "true";
            button.setAttribute("aria-expanded", String(!isOpen));
            panel.hidden = isOpen;
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
              button.setAttribute("aria-expanded", "false");
              panel.hidden = true;
              button.focus();
            }
          });
        });
      }

      document.getElementById("app").innerHTML = FAQPage({ items: faqs });
      initDisclosures();
    </script>
  </body>
</html>
